def make_question(index, row):
    tag, prompt, options, answer, reason = row
    opts = [{"id": chr(65+i), "text": text} for i, text in enumerate(options)]
    aid = next(o["id"] for o in opts if o["text"] == answer)
    refs = [{"url": u, "title": f"{t}；僅研究公開題型與能力方向，未複製原題。", "year": "113-114", "subject": "social", "locator": l, "observedPattern": "公立學校社會科公開試題常見的經緯度、方位與地圖資料判讀能力，經本題重新設計。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for u,t,l in SOURCES]
    steps = [f"讀題定位：圈出「{tag}」的緯度、經度、方向、基準線與表示格式。", f"建立判準：先分辨南北由緯度判斷、東西由經度判斷；本題理由是「{reason}」。", f"核對正解：選項 {aid}「{answer}」符合座標定義與題幹條件。", "排除誘答：檢查是否倒置經緯度、混淆方向、漏掉半球或把精度誤當正確性。", "回查定位：把答案放回地圖或座標格式，確認方向、數值與交點一致；若資料改變要重新計算。"]
    return {"id": f"question-social-content-geo-aa-iv-1-{index}", "subject": "social", "type": "single-choice", "prompt": prompt, "options": opts, "knowledgeIds": ["kg-social-content-geo-aa-iv-1"], "difficulty": "medium", "answer": {"value": aid, "explanation": reason}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0][0], "sourceLocator": "高雄市立鹽埕國中三年級社會科公開段考；本題只研究公開試題能力結構與資料型態。", "authoringNote": "依官方課綱、單元 KG 與三個公立學校公開來源的題型方向，獨立改寫全球經緯度座標情境；未複製原文、選項、圖表或答案；待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-09", "lessonId": "lesson-social-content-geo-aa-iv-1", "examPatternRefs": refs, "solutionStrategy": "先固定赤道與本初子午線，再分清緯度／經度、南北／東西與度分秒格式，最後用交點和半球回查。", "solutionSteps": steps}

for index, row in enumerate(DATA, 1):
    (OUT / f"question-social-content-geo-aa-iv-1-{index}.json").write_text(json.dumps(make_question(index, row), ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(f"rewrote {len(DATA)} questions")
